  const lvl=grp(r=>String(r.lvlRaw||'').trim()||'—');
  const d30=act.filter(r=>r.days!=null&&r.days>=0&&r.days<=30&&r.status!=='progress').length, d90=act.filter(r=>r.days!=null&&r.days>=0&&r.days<=90&&r.status!=='progress').length;
