/* ======================= 2. KOMPLEKS ======================= */
RP.calcKomp = function(f){
  let rows=KOMPLEKS.slice();
  if(f.edu) rows=rows.filter(r=>dbEduKey(r.edu)===f.edu);
  if(f.own) rows=rows.filter(r=>dbOwnKey(r.own)===f.own);
  if(f.from||f.to) rows=rows.filter(r=>inPeriod(r.cDate,f));
  rows=rows.map(r=>Object.assign({region:regionOfName(r.hei)}, r));
  if(f.region) rows=rows.filter(r=>r.region===f.region);
  const n=rows.length, st=k=>rows.filter(r=>r.stage===k).length;
  const done=st('done'), passed=rows.filter(r=>r.result==='passed').length, failed=rows.filter(r=>r.result==='failed').length;
  const open=rows.filter(r=>r.stage!=='done');
  const age=r=>kAge(r,f.ref); const ages=open.map(age).filter(x=>x!=null);
  const warn=open.filter(r=>{const a=age(r); return a!=null&&a>RP.cfg.waitWarn&&a<=RP.cfg.waitCrit;}).length;
  const crit=open.filter(r=>{const a=age(r); return a!=null&&a>RP.cfg.waitCrit;}).length;
  const accD=rows.map(r=>kAccDays(r)).filter(x=>x!=null);
  const stageAge={}; K_ORDER.forEach(k=>{ const a=rows.filter(r=>r.stage===k).map(age).filter(x=>x!=null); stageAge[k]={n:a.length, avg:a.length?sum(a)/a.length:0, med:a.length?kMedian(a):0, max:a.length?Math.max(...a):0}; });
  const month={}; rows.forEach(r=>{ if(r.cDate) { const k=r.cDate.slice(0,7); month[k]=month[k]||{n:0,done:0}; month[k].n++; if(r.stage==='done') month[k].done++; } });
  const grp=fn=>{ const m={}; rows.forEach(r=>{ const k=fn(r); if(k==null) return; if(!m[k]) m[k]={n:0,done:0,passed:0,failed:0,crit:0,warn:0,open:0,ages:[]}; const g=m[k]; g.n++; if(r.stage==='done'){ g.done++; if(r.result==='passed') g.passed++; if(r.result==='failed') g.failed++; } else { g.open++; const a=age(r); if(a!=null){ g.ages.push(a); if(a>RP.cfg.waitCrit) g.crit++; else if(a>RP.cfg.waitWarn) g.warn++; } } }); Object.values(m).forEach(g=>{ g.avgAge=g.ages.length?sum(g.ages)/g.ages.length:0; g.critRate=sd(g.crit,g.open); }); return m; };
  const edu=grp(r=>dbEduKey(r.edu)), own=grp(r=>dbOwnKey(r.own)), reg=grp(r=>r.region), stageEdu={};
  K_ORDER.forEach(k=>{ stageEdu[k]=by(rows.filter(r=>r.stage===k), r=>dbEduKey(r.edu)); });
  const orgs=new Set(rows.map(r=>dbNorm(r.hei))).size;
  const regionCoverage=sd(rows.filter(r=>r.region).length,n);
  const prots=[...new Set(rows.filter(r=>r.prot).map(r=>r.prot))].sort();
  const accepted=rows.filter(r=>r.aDate).length;
  return {n, orgs, st, done, passed, failed, open:open.length, ages, avgAge:ages.length?sum(ages)/ages.length:0, medAge:ages.length?kMedian(ages):0, warn, crit, ok:open.length-warn-crit, accAvg:accD.length?sum(accD)/accD.length:0, accN:accD.length, accepted, stageAge, month, edu, own, reg, stageEdu, regionCoverage, prots, rows, noDate:rows.filter(r=>!r.cDate).length};
};
