RP.calcMx = function(f){
  let P=PROGRAMS.slice(); const appMap={}; APPS.forEach(a=>appMap[a.app]=a);
  if(f.edu) P=P.filter(p=>dbEduKey(p.edu)===f.edu);
  if(f.own) P=P.filter(p=>dbOwnKey(p.own)===f.own);
  if(f.lvl) P=P.filter(p=>(p.lvl||'')===f.lvl);
  if(f.field) P=P.filter(p=>(p.field||'')===f.field);
  if(f.from||f.to) P=P.filter(p=>{ const a=appMap[p.app]; return a?inPeriod(a.cDate,f):true; });
  P=P.map(p=>Object.assign({region:regionOfName(p.hei)},p));
  if(f.region) P=P.filter(p=>p.region===f.region);
  const n=P.length, passed=P.filter(p=>p.status==='passed').length, failed=P.filter(p=>p.status==='failed').length, pending=P.filter(p=>p.status==='inProgress').length, decided=passed+failed;
  const orgs=new Set(P.map(p=>dbNorm(p.hei))).size, apps=new Set(P.map(p=>p.app)).size;
  const grp=fn=>{ const m={}; P.forEach(p=>{ const k=fn(p); if(k==null||k==='') return; if(!m[k]) m[k]={n:0,passed:0,failed:0,pending:0}; m[k].n++; m[k][p.status==='inProgress'?'pending':p.status]++; }); Object.values(m).forEach(g=>{ g.decided=g.passed+g.failed; g.succ=sd(g.passed,g.decided); g.share=sd(g.passed,g.n); g.pendShare=sd(g.pending,g.n); g.small=g.decided<RP.cfg.smallSample; }); return m; };
  const edu=grp(p=>dbEduKey(p.edu)), lvl=grp(p=>p.lvl||'—'), own=grp(p=>dbOwnKey(p.own)), field=grp(p=>p.field||'Aniqlanmagan'), hei=grp(p=>p.hei), reg=grp(p=>p.region), dec=grp(p=>p.dec||'');
  const succ=sd(passed,decided);
  const multiFail=Object.entries(hei).filter(h=>h[1].failed>=2).sort((a,b)=>b[1].failed-a[1].failed);
  const regionCoverage=sd(P.filter(p=>p.region).length,n);
  return {n, passed, failed, pending, decided, succ, shareAcc:sd(passed,n), sharePend:sd(pending,n), orgs, apps, edu, lvl, own, field, hei, reg, dec, multiFail, regionCoverage, rows:P};
};
